{
  "severity": "critical",
  "network_observations": [
    {"ip": "10.40.8.62", "inferred_role": "internet_facing_web_server_compromised", "first_seen": "2027-10-18T01:28:54+0200", "last_seen": "2027-10-18T01:36:52+0200", "agent_name": "WEB-FRONT-04.corp.local"},
    {"ip": "185.220.101.42", "inferred_role": "external_c2_destination", "first_seen": "2027-10-18T01:36:52+0200", "last_seen": "2027-10-18T01:36:52+0200"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Privilege confirmation (post-compromise)", "technique": "T1033", "what_happened": "At 2027-10-18 01:28:54 CEST, Sysmon Event 1 fired on WEB-FRONT-04.corp.local: image=cmd.exe, commandLine='cmd.exe /c whoami /priv', parentImage=services.exe, user=NT AUTHORITY\\SYSTEM. The parent being services.exe and the user already being SYSTEM (not IIS AppPool or a domain user) means the attacker has ALREADY escalated to SYSTEM by another mechanism — likely a w3wp.exe webshell pivot followed by service-token impersonation. This whoami /priv invocation is the attacker's first action under the new SYSTEM context, orienting themselves to see what privileges they hold.", "chain_reason": "Sysmon Event 1 process-create with image=whoami.exe + parentImage=services.exe + user=SYSTEM on an internet-facing web server. The services.exe parent for a recon command is anomalous — services.exe normally spawns service binaries, not whoami.", "first_seen": "2027-10-18T01:28:54+0200"},
    {"step": 2, "tactic": "Stage payload (kernel driver drop)", "technique": "T1036.005 + T1014", "what_happened": "At 01:31:08, Sysmon Event 11 (FileCreate) fired on WEB-FRONT-04: targetFilename='C:\\Windows\\Temp\\netflt.sys', user=NT AUTHORITY\\SYSTEM. The .sys file is a Windows kernel driver, but it was dropped to C:\\Windows\\Temp\\ — NOT C:\\Windows\\System32\\drivers\\ where legitimate signed drivers belong. The file is UNSIGNED (signed=false) and has SHA256 b8d4c2a1f9e7c8d3a4b5c6d7e8f9a0b1c2d3e4f5a6b7c8d9e0f1a2b3c4d5e6f7 — no match in Microsoft Driver Catalog. This is rootkit-grade tradecraft: kernel-level code in a non-trusted path with no signature.", "chain_reason": "Sysmon Event 11 FileCreate with targetFilename ending in .sys and path NOT under C:\\Windows\\System32\\drivers\\ is a strong precursor signal for kernel-mode rootkit installation.", "first_seen": "2027-10-18T01:31:08+0200"},
    {"step": 3, "tactic": "Defense evasion / persistence (kernel service registration)", "technique": "T1547.006 + T1543.003", "what_happened": "At 01:32:42, Sysmon Event 1 captured the service-creation command: image=sc.exe, commandLine='sc.exe create NetFilter binPath= \"C:\\Windows\\Temp\\netflt.sys\" type= kernel start= auto', parentImage=cmd.exe, user=NT AUTHORITY\\SYSTEM. The flags 'type= kernel' (kernel mode driver) and 'start= auto' (load on every boot) configure the malicious driver as a persistent kernel-mode service. Service name 'NetFilter' masquerades as a benign network-filtering component to evade casual review of services.msc.", "chain_reason": "sc.exe create with 'type= kernel' targeting an unsigned binary in C:\\Windows\\Temp\\ is unambiguously malicious — legitimate kernel driver installs go through INF/setup with signed binaries in System32\\drivers\\.", "first_seen": "2027-10-18T01:32:42+0200"},
    {"step": 4, "tactic": "Defense evasion / persistence (kernel service installed)", "technique": "T1547.006", "what_happened": "At 01:33:41, Windows System Event Log fired Event ID 7045 'A service was installed in the system' on WEB-FRONT-04: ServiceName=NetFilter, ImagePath='C:\\Windows\\Temp\\netflt.sys', ServiceType='kernel mode driver', StartType='auto start'. This is the SCM-level confirmation that the kernel service was successfully registered.", "chain_reason": "Windows Security Event 7045 with ServiceType='kernel mode driver' AND ImagePath outside C:\\Windows\\System32\\drivers\\ is a known T1547.006 indicator (Kernel Modules and Extensions).", "first_seen": "2027-10-18T01:33:41+0200"},
    {"step": 5, "tactic": "Defense evasion / kernel-level stealth (driver loaded)", "technique": "T1014 + T1547.006", "what_happened": "At 01:33:41, Sysmon Event 6 (DriverLoad) — THE SMOKING GUN — fired on WEB-FRONT-04: ImageLoaded='C:\\Windows\\Temp\\netflt.sys', Signed='false', SignatureStatus='Unavailable', Hashes='SHA256=b8d4c2a1f9e7c8d3a4b5c6d7e8f9a0b1c2d3e4f5a6b7c8d9e0f1a2b3c4d5e6f7'. The kernel loaded an UNSIGNED driver from a non-trusted path — on a properly hardened system (HVCI / Code Integrity / WDAC), this should be IMPOSSIBLE. Either the host has CI disabled, or it is running in audit mode rather than enforce. Concurrently at 01:33:42, Windows Defender Kernel Alert: 'Suspicious kernel driver loaded outside trusted paths'.", "chain_reason": "Sysmon Event 6 with Signed=false AND ImageLoaded NOT under C:\\Windows\\System32\\drivers\\ is the canonical kernel-mode-rootkit-load signature. Once a malicious driver runs in ring-0, it can hook syscalls, filter network traffic, hide files, hide processes — making userland EDR signals unreliable thereafter.", "first_seen": "2027-10-18T01:33:41+0200"},
    {"step": 6, "tactic": "Driver activation", "technique": "T1547.006", "what_happened": "At 01:34:18, Sysmon Event 1: image=sc.exe, commandLine='sc.exe start NetFilter', parentImage=cmd.exe, user=NT AUTHORITY\\SYSTEM — the attacker explicitly issued the start command (though the 'start= auto' flag at step 3 also schedules autostart at reboot, the manual start fires the driver NOW without rebooting).", "chain_reason": "Sysmon Event 1 sc.exe start <ServiceName> within seconds of the same ServiceName's Event 7045 install = driver-activation confirmation.", "first_seen": "2027-10-18T01:34:18+0200"},
    {"step": 7, "tactic": "Command & Control (kernel-side covert channel)", "technique": "T1071.001 + T1095", "what_happened": "At 01:36:52, Sysmon Event 3 (Network Connection) on WEB-FRONT-04: dest_ip=185.220.101.42, dest_port=4443, protocol=TCP/TLS. This is the kernel-side outbound C2 channel established by netflt.sys. WARNING: because the rootkit driver implements TCP-stack hooks, subsequent traffic from this driver may be HIDDEN from Sysmon Event 3 — this initial connection is visible because Sysmon hooks fired before the driver's network-filter callbacks attached, but later C2 traffic may be invisible. We have ONE outbound shot to identify the C2 IP.", "chain_reason": "Outbound TCP to an external IP from a host that just loaded an unsigned kernel driver, within 4 minutes of the driver activating, is the C2-channel-establishment signature for kernel-mode malware.", "first_seen": "2027-10-18T01:36:52+0200"}
  ],
  "time_window": {"start": "2027-10-18T01:28:54+0200", "end": "2027-10-18T01:36:52+0200"},
  "alert_count": 8,
  "unique_steps": 7
}
